const r = await tools.exec_command({cmd:"cat > /app/answer.py <<'PY'
import csv
import json
from decimal import Decimal


DATA_DIR = "/app/dataset"
# This simultaneous cold-chain batch coincides with the July 18 temperature
# excursion in the Meat and Frozen zones and is the clear spoilage write-off.
DISPOSAL_DISPATCH_IDS = {127, 128, 129, 130, 131, 132, 133, 134}


def answer() -> int:
    catalog = {}
    with open(f"{DATA_DIR}/product_catalog.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            product = (Decimal(row["unit_price"].replace(",", ".")))
            catalog[row["product_id"]] = product
            # One dispatch uses the item's EAN instead of its product_id.
            catalog[row["ean_code"]] = product

    total = Decimal("0")
    with open(f"{DATA_DIR}/warehouse_dispatches.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if not row["timestamp"].startswith("2023-07-"):
                continue
            if int(row["dispatch_id"]) in DISPOSAL_DISPATCH_IDS:
                continue
            unit_price = catalog[row["product_id"]]
            total += unit_price * int(row["quantity"])

    return int(total)


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
